-- Herb and skinning lines (from Herbalore, folded into Shan'do 7 Nov 2026). Voice files in sounds/herbs/
local _, ns = ...
ns.HERBS = {
    ["Peacebloom"] = { { "peacebloom", "Peacebloom. The first herb most healers ever learn to pick. It asks nothing of you, and it grows wherever there is a little peace to spare." }, { "peacebloom_2", "Peacebloom again. Some druids keep one pressed in their satchel, just to remember where they started." }, { "peacebloom_3", "Small, white, and everywhere. The world is generous with the gentle things, if you look." }, { "peacebloom_4", "Peacebloom closes a little at night, like hands folding. Even flowers rest." }, { "peacebloom_5", "A healer's first bandage, a child's first posy. Peacebloom has been both." }, { "peacebloom_6", "Most of a plant is hidden below. For every bloom you see, there's a quiet web of roots holding the soil together." }, { "peacebloom_7", "Bees visit it all day long. You're in good company." }, { "peacebloom_8", "Take a breath before you pick the next one. Peacebloom isn't in a hurry, so neither are we." } },
    ["Silverleaf"] = { { "silverleaf", "Silverleaf. Turn it in the light and you'll see why it has the name. Small things are worth noticing." }, { "silverleaf_2", "Silverleaf likes the edges of paths. It has watched more travellers pass than any of us." }, { "silverleaf_3", "Hold it up to the moon sometime. It glows almost the same colour." }, { "silverleaf_4", "That silver sheen is the leaf catching light it can't use, and giving it back to you." }, { "silverleaf_5", "Silverleaf grows best on ground that's been walked. It likes being near travellers." }, { "silverleaf_6", "A small herb with a soft shine. The White Lady would approve." }, { "silverleaf_7", "Every leaf is turned toward the sky, as if listening." }, { "silverleaf_8", "Run a thumb along it. Soft on one side, cool on the other." } },
    ["Earthroot"] = { { "earthroot", "Earthroot. It likes the feet of hills and the shelter of stones. Steady, patient, and holding on." }, { "earthroot_2", "Earthroot never hurries. It takes its time, and it takes hold." }, { "earthroot_3", "Brush the soil from it gently. The hills gave it up for you." }, { "earthroot_4", "Earthroot's roots go down further than its leaves go up. It knows where its strength is." }, { "earthroot_5", "Smell the soil on it. That's the smell of a living forest floor." }, { "earthroot_6", "The fine threads on the roots aren't all its own. Some belong to the fungi it trades with, sugar for water." }, { "earthroot_7", "Hills hold their roots the way old friends hold hands. Quietly, and for a long time." }, { "earthroot_8", "Steady things are easy to overlook. Not today." } },
    ["Mageroyal"] = { { "mageroyal", "Mageroyal. A proud little flower, for one that grows by the roadside." }, { "mageroyal_2", "Mageroyal. Bright as a little flame, and just as eager." }, { "mageroyal_3", "A royal name for a roadside flower. It doesn't seem to mind which." }, { "mageroyal_4", "Mageroyal turns its face to follow the sun across the day." }, { "mageroyal_5", "A bright little crown on a thin stem. It carries itself well." }, { "mageroyal_6", "The colour is for the bees. Flowers dress up for their visitors." }, { "mageroyal_7", "It grows by the roadside, where everyone passes and few look. You looked." }, { "mageroyal_8", "Even a small flower can make a clearing feel like a celebration." } },
    ["Briarthorn"] = { { "briarthorn", "Briarthorn. Mind your fingers. Even the thorns are only keeping something safe." }, { "briarthorn_2", "Briarthorn guards itself. Gloves, or patience. Patience is better." }, { "briarthorn_3", "Even the thorny ones are worth the care. Most good things are." }, { "briarthorn_4", "Briarthorn's thorns are older than any blade. The world learned guarding from plants like this." }, { "briarthorn_5", "Thorns keep grazing beasts away so the flowers can set seed. Protection, not spite." }, { "briarthorn_6", "Slowly, from the base of the stem. It gives itself up more kindly that way." }, { "briarthorn_7", "Birds nest in thickets like these. The thorns keep the little ones safe." }, { "briarthorn_8", "Being careful with something prickly is a kind of respect." } },
    ["Swiftthistle"] = { { "swiftthistle", "Swiftthistle. It hides among other herbs and comes to you as a small surprise. The alchemists make swiftness from it." }, { "swiftthistle_2", "Swiftthistle hides in the shade of other herbs. A small gift for those who look twice." }, { "swiftthistle_3", "Quick to find, quick to fade. Enjoy it while it's here." }, { "swiftthistle_4", "Swiftthistle's down floats off on the lightest breeze. Every seed a small traveller." }, { "swiftthistle_5", "A thistle that's quick to grow and quick to go. Some lives are short and bright." }, { "swiftthistle_6", "You found it in another herb's shadow. Good eyes." }, { "swiftthistle_7", "It never stays in one place long. The wind is its road." }, { "swiftthistle_8", "A little speed in a leaf. Saved for the day you need it." } },
    ["Bruiseweed"] = { { "bruiseweed", "Bruiseweed. An ugly name for a plant that helps things mend." }, { "bruiseweed_2", "A dusty leaf from a dusty slope. The healers will turn it into comfort." }, { "bruiseweed_3", "It grows in the hard places, between rocks. Stubborn and kind at once." }, { "bruiseweed_4", "Bruiseweed grows thick on dry slopes, holding the soil down when the rains come." }, { "bruiseweed_5", "Plants like this heal the ground first, and people second." }, { "bruiseweed_6", "Crush a leaf, if you like, and smell it. Bitter, green, honest." }, { "bruiseweed_7", "Not every helper is pretty. Most of them aren't, really." }, { "bruiseweed_8", "Bruises fade. So do hard days. This leaf knows." } },
    ["Stranglekelp"] = { { "stranglekelp", "Stranglekelp. The sea keeps its own garden. Take a breath before you go down for it." }, { "stranglekelp_2", "Kelp, swaying in the current like a slow green dance. Watch it a moment before you take some." }, { "stranglekelp_3", "Cold and green and swaying. Even underwater, the world breathes." }, { "stranglekelp_4", "Kelp isn't quite a plant. It's an older kind of life, from before roots, drinking light through the water." }, { "stranglekelp_5", "Underwater forests sway like this all the time. The sea is always breathing." }, { "stranglekelp_6", "Fish shelter in kelp the way birds shelter in trees. A whole village down there." }, { "stranglekelp_7", "Come up slowly, and take a good breath. The kelp can wait." }, { "stranglekelp_8", "It grips the rocks so the tide can't take it. Holding on, and still moving." } },
    ["Wild Steelbloom"] = { { "wild_steelbloom", "Wild Steelbloom. A flower that decided to be as tough as the hills around it." }, { "wild_steelbloom_2", "Steel in the name, petals in the hand. It's allowed to be both." }, { "wild_steelbloom_3", "It grows where the ground is hard. It doesn't complain about it." }, { "wild_steelbloom_4", "Wild Steelbloom grows in stony ground where softer things give up." }, { "wild_steelbloom_5", "A hard stem and a soft petal. Strength doesn't have to mean being hard all the way through." }, { "wild_steelbloom_6", "The hills around it are made of iron and patience. So is the flower." }, { "wild_steelbloom_7", "Wind-bent, sun-baked, and still blooming. A good teacher, that." }, { "wild_steelbloom_8", "Stand in the wind a moment, like it does. The ground holds you as it holds the flower." } },
    ["Grave Moss"] = { { "grave_moss", "Grave Moss. It grows where the dead are laid. Pick it gently. Someone was remembered here." }, { "grave_moss_2", "Grave Moss. Life, even here. Especially here." }, { "grave_moss_3", "Pick it softly. Whoever rests beneath won't mind a little company." }, { "grave_moss_4", "Moss has no roots at all. It holds on with tiny threads, and drinks the rain and dew straight through its leaves." }, { "grave_moss_5", "Mosses were among the first green things to leave the water. They've been softening stone ever since." }, { "grave_moss_6", "A green blanket over old stones. The forest tucking someone in." }, { "grave_moss_7", "Moss can dry out for months and wake with the first rain. Patience, written in green." }, { "grave_moss_8", "Quiet places grow the softest things." } },
    ["Kingsblood"] = { { "kingsblood", "Kingsblood. A grand name for a quiet plant. Kings come and go. The herb is still here." }, { "kingsblood_2", "Kingsblood. Deep red, and proud of it. Every herb has its own way of standing tall." }, { "kingsblood_3", "A royal name for a wild thing. It answers to no king at all." }, { "kingsblood_4", "Kingsblood's red comes from the same colours that turn autumn leaves. Sunlight, kept." }, { "kingsblood_5", "It stands up straight among the grasses, as if waiting to be noticed. Notice it." }, { "kingsblood_6", "Plenty of things are named for kings. Few of them grow back every spring." }, { "kingsblood_7", "A deep colour for a quiet field. Like a heartbeat in the grass." }, { "kingsblood_8", "Gather it kindly. Real nobility is gentle." } },
    ["Liferoot"] = { { "liferoot", "Liferoot. It follows the water, and drinks from the riverbanks. Where it grows, things are alive." }, { "liferoot_2", "The sound of running water, and there it is. Liferoot never strays far from a river." }, { "liferoot_3", "Its name says everything. Life, and roots. What more do any of us need?" }, { "liferoot_4", "Liferoot drinks so much that the riverbanks stay firm around it. It gives back by holding on." }, { "liferoot_5", "Listen. Water nearby. Where water goes, life follows." }, { "liferoot_6", "Its roots are thick and pale, full of everything it's gathered. A living store for hard times." }, { "liferoot_7", "Rivers carve the land, and plants like this hold it together. Between them, a valley." }, { "liferoot_8", "Rinse it in the river if you like. It's at home there." } },
    ["Fadeleaf"] = { { "fadeleaf", "Fadeleaf. It prefers the shade, and it's easy to walk past. Most of the best things are." }, { "fadeleaf_2", "Fadeleaf. Look away and it's half gone. Look back, and it was always there." }, { "fadeleaf_3", "Rogues love it for hiding. You can love it for being quietly lovely." }, { "fadeleaf_4", "Fadeleaf has shade leaves: wide and thin, catching every bit of light under the canopy." }, { "fadeleaf_5", "In the dim, it wastes nothing. A good way to live through a grey season." }, { "fadeleaf_6", "Quiet colours, quiet places. Not everything needs to shine." }, { "fadeleaf_7", "Some things are only found by those who move slowly." }, { "fadeleaf_8", "Let your eyes adjust to the shade. There's more here than you first saw." } },
    ["Goldthorn"] = { { "goldthorn", "Goldthorn. It catches the evening light on the hillsides. Take a moment to watch it." }, { "goldthorn_2", "Goldthorn. Gold that grows. The only kind worth having, really." }, { "goldthorn_3", "A thorn with a golden edge. Careful hands, and it gives itself up easily." }, { "goldthorn_4", "Goldthorn's flowers are shaped for bees. The petals make a landing place, and the nectar's tucked deep." }, { "goldthorn_5", "A golden edge on a thorny stem. The best things are often a little guarded." }, { "goldthorn_6", "Late afternoon light, and goldthorn on the hill. That's a picture worth keeping." }, { "goldthorn_7", "Bees can see colours on its petals that we can't. Paths drawn in light, leading to the nectar." }, { "goldthorn_8", "It's rich in the only way that matters to a hillside: it feeds things." } },
    ["Khadgar's Whisker"] = { { "khadgars_whisker", "Khadgar's Whisker. Named for the archmage, and said to look a little like his beard. Even legends end up as herbs, eventually." }, { "khadgars_whisker_2", "Khadgar's Whisker. Named for a wizard, but it was here first." }, { "khadgars_whisker_3", "Thin and wiry and wise-looking. It suits the name." }, { "khadgars_whisker_4", "Thin and tangled, like a beard nobody's combed. It's earned that look." }, { "khadgars_whisker_5", "It grows in the damp and the dappled. Not every wise thing lives in a tower." }, { "khadgars_whisker_6", "A plant named after a wizard. The plant doesn't seem bothered either way." }, { "khadgars_whisker_7", "Wiry things bend instead of breaking. Worth remembering." }, { "khadgars_whisker_8", "Untangle it gently. Hurried fingers tear what patient ones keep whole." } },
    ["Wintersbite"] = { { "wintersbite", "Wintersbite. It only grows in the cold of the Alterac Mountains. It bites back, a little." }, { "wintersbite_2", "Wintersbite. It blooms in the cold because nobody told it not to." }, { "wintersbite_3", "Frost on the petals and a bite in the air. Wrap up warm." }, { "wintersbite_4", "Cold-country plants grow low and slow, keeping out of the wind." }, { "wintersbite_5", "Its leaves are tough and small, holding on to every bit of warmth." }, { "wintersbite_6", "Breathe out and watch your breath hang in the air. Wintersbite lives in that kind of cold, every day." }, { "wintersbite_7", "Snow is a blanket, for plants. Under it, they're warmer than you'd think." }, { "wintersbite_8", "Hard winters make for clear skies. Look up later, if you can." } },
    ["Firebloom"] = { { "firebloom", "Firebloom. It loves the hottest, driest lands, where little else will grow." }, { "firebloom_2", "Firebloom. It drinks the heat and gives back colour." }, { "firebloom_3", "Where the ground is scorched, it grows anyway. A little hope in a hard place." }, { "firebloom_4", "Firebloom keeps its water close and opens only when it's ready. Desert plants don't waste a drop." }, { "firebloom_5", "Some seeds in hot lands only wake after a fire. Something new, out of the ashes." }, { "firebloom_6", "The ground's warm even through your boots. Take a sip of water while you're here." }, { "firebloom_7", "Bright as embers, but it doesn't burn. It only glows." }, { "firebloom_8", "In a dry land, every flower is a small promise of rain." } },
    ["Purple Lotus"] = { { "purple_lotus", "Purple Lotus. A lotus that grows out of hard country. Beautiful things don't always need soft ground." }, { "purple_lotus_2", "Purple Lotus. It floats like it has nowhere to be. Take the hint." }, { "purple_lotus_3", "Lotus petals open slowly. There's no rushing a flower." }, { "purple_lotus_4", "A lotus's leaves shed water like pearls. Nothing muddy sticks to them." }, { "purple_lotus_5", "Lotus seeds can wait a very long time before they sprout. They'll open when the moment's right." }, { "purple_lotus_6", "It rises clean out of the mud. Where you start isn't where you have to stay." }, { "purple_lotus_7", "Purple was a rare colour once, saved for the sacred. Here it's just growing in the open." }, { "purple_lotus_8", "Still water, open petals. Let your shoulders open too, if they'd like to." } },
    ["Arthas' Tears"] = { { "arthas_tears", "Arthas' Tears. It grows where the plague passed through. Even grief can flower, given long enough." }, { "arthas_tears_2", "A pale little flower with a heavy name. It didn't choose the name. It only chose to grow." }, { "arthas_tears_3", "They grow where the land was hurt. The land remembers, and it heals anyway." }, { "arthas_tears_4", "Plants are often the first to come back to hurt ground. They make it soft enough for everything else." }, { "arthas_tears_5", "A gentle flower in a land that's known a lot of pain. Healing starts small." }, { "arthas_tears_6", "Whatever the name, the petals are soft. Hold them that way." }, { "arthas_tears_7", "Each one you see is the land saying \"not finished yet\"." }, { "arthas_tears_8", "Breathe. Even here, the air carries a little green." } },
    ["Sungrass"] = { { "sungrass", "Sungrass. It spreads across open land under a wide sky. Stand up straight for a moment, and feel the sun." }, { "sungrass_2", "Sungrass. It holds the light of long afternoons. Take some with you." }, { "sungrass_3", "Warm to the touch, almost. As if it's been listening to the sun all day." }, { "sungrass_4", "Grasses have no need of bees. They give their pollen to the wind, and trust it." }, { "sungrass_5", "Grass grows from the base, not the tip. Cut it, graze it, and it simply keeps going." }, { "sungrass_6", "A whole meadow moving together in the wind. Watch it, for a breath or two." }, { "sungrass_7", "Sungrass smells like long afternoons. Hold some up and see." }, { "sungrass_8", "Open sky, warm grass, nowhere to be. That's a good moment." } },
    ["Blindweed"] = { { "blindweed", "Blindweed. A plant of the swamps and the deep wet places. The marsh is full of life, if you're slow enough to see it." }, { "blindweed_2", "Frogs, reeds, the smell of wet earth. Blindweed's home is a busy one." }, { "blindweed_3", "Careful in the mire. Step where the roots are; they know the ground." }, { "blindweed_4", "Swamp plants breathe through their stems, sending air down to roots in the mud." }, { "blindweed_5", "The marsh looks still, but it's one of the busiest places in the world. Listen." }, { "blindweed_6", "Frogs sing, flies drift, the water barely moves. A slow kind of song." }, { "blindweed_7", "Mud and shadow, and still it grows. Every place is somebody's home." }, { "blindweed_8", "Wet boots, quiet mind. There are worse trades." } },
    ["Ghost Mushroom"] = { { "ghost_mushroom", "Ghost Mushroom. It glows faintly in the dark places. Even down here, something is growing." }, { "ghost_mushroom_2", "Ghost Mushroom. A little lantern for the dark places." }, { "ghost_mushroom_3", "Quiet down here. The mushrooms keep the caves company." }, { "ghost_mushroom_4", "A mushroom is only the flower of the fungus. The rest of it runs through the ground for a long, long way." }, { "ghost_mushroom_5", "Some fungi glow in the dark. Nobody's quite sure why. A small mystery, shining." }, { "ghost_mushroom_6", "Fungi are the forest's quiet healers. They turn what's fallen back into soil." }, { "ghost_mushroom_7", "Down here, the light comes from the living. That's a comforting thought." }, { "ghost_mushroom_8", "Cave air, cool and still. Rest your eyes in the dim for a moment." } },
    ["Gromsblood"] = { { "gromsblood", "Gromsblood. Named for Grom Hellscream, who fell, and rose, and paid for it. The land remembers him in red." }, { "gromsblood_2", "Gromsblood. A fierce name. It grows where the land is wounded, and it still grows." }, { "gromsblood_3", "Dark and bitter. Not every gift is gentle, but it is still a gift." }, { "gromsblood_4", "A dark red stem from scorched ground. The land doesn't give up easily." }, { "gromsblood_5", "Gromsblood loves the broken places. Something always grows in the gaps." }, { "gromsblood_6", "It's a hard name for a hardy plant. Both have weathered a lot." }, { "gromsblood_7", "Old stories cling to herbs like dew. You don't have to carry them." }, { "gromsblood_8", "Bitter herbs make strong medicine. That's been true a long time." } },
    ["Golden Sansam"] = { { "golden_sansam", "Golden Sansam. Warm in the hand, and worth the walk. The healers prize it." }, { "golden_sansam_2", "Golden Sansam. A warm colour for a warm place. Breathe it in." }, { "golden_sansam_3", "Some herbs ask to be found. Sansam just waits, glowing." }, { "golden_sansam_4", "Golden Sansam glows like a lamp left on in a window. Someone's expecting you." }, { "golden_sansam_5", "Warm colours, warm hands, warm heart. That's the herbalist's way." }, { "golden_sansam_6", "It grows in the rich soil of the wilds, where many seasons have fallen and been turned back into earth." }, { "golden_sansam_7", "Each one's a little sun you can carry." }, { "golden_sansam_8", "Healers have relied on herbs like this for longer than anyone can remember. You're part of that line now." } },
    ["Dreamfoil"] = { { "dreamfoil", "Dreamfoil. Some say it carries a little of the Emerald Dream in its leaves. A druid would know." }, { "dreamfoil_2", "The druids who sleep in the barrow dens walk the Dream for years. A leaf of it is plenty for one afternoon." }, { "dreamfoil_3", "Pick it gently, as if you might wake it." }, { "dreamfoil_4", "Dreamfoil's leaves fold gently, as if sleeping." }, { "dreamfoil_5", "Druids say the Dream is the world as it might be, untouched. Somewhere, this leaf is perfect." }, { "dreamfoil_6", "Pale green and soft as a whisper. Lower your voice, if you like." }, { "dreamfoil_7", "Some plants seem to belong to two worlds at once. This is one." }, { "dreamfoil_8", "Sleep well tonight. Dreamfoil would want that for you." } },
    ["Mountain Silversage"] = { { "mountain_silversage", "Mountain Silversage. It grows high, where the air is thin and clean. Breathe it in." }, { "mountain_silversage_2", "Mountain Silversage. Worth the climb. Turn round, if you like, and see how far you've come." }, { "mountain_silversage_3", "Silver in the leaves and snow in the wind. Worth every step." }, { "mountain_silversage_4", "Mountain plants are small and close to the ground. Up here, the wind decides everything." }, { "mountain_silversage_5", "The silver is a coat of fine hairs, keeping out the cold sun and the drying wind." }, { "mountain_silversage_6", "Sage smoke has long been used to clear the air, and the mind. This one smells of both." }, { "mountain_silversage_7", "High places make things simple. Air, stone, sky, you." }, { "mountain_silversage_8", "Look out across the land, if you like. You came a long way up." } },
    ["Plaguebloom"] = { { "plaguebloom", "Plaguebloom. It grows from tainted ground and turns that taint into medicine. Healing often starts in the worst places." }, { "plaguebloom_2", "Plaguebloom. The soil is sick, but the flower still opens. The land is fighting for itself." }, { "plaguebloom_3", "Every one you pick is one less sorrow in the soil." }, { "plaguebloom_4", "Some plants draw poison out of the soil and lock it in their leaves. Gardeners of hurt ground." }, { "plaguebloom_5", "Every Plaguebloom picked is a little sickness taken out of the soil." }, { "plaguebloom_6", "Strange colours for a strange land. It's still trying to be a flower." }, { "plaguebloom_7", "Gloves on. Gentle anyway." }, { "plaguebloom_8", "Wounded land heals from the edges in. You're working at one of the edges." } },
    ["Icecap"] = { { "icecap", "Icecap. A flower of Winterspring's snow. It has learned how to bloom in the cold." }, { "icecap_2", "Icecap. It grows under the snow, waiting. Patience made into a plant." }, { "icecap_3", "Cold fingers, warm heart. That's how you gather Icecap." }, { "icecap_4", "Snow lets light through. Under it, plants keep growing, slowly, in a blue half-light." }, { "icecap_5", "Icecap is mostly patience, frozen into a flower." }, { "icecap_6", "Your breath on the petals. A little warmth in a cold place." }, { "icecap_7", "The stars are sharp up here. Look up, when your hands are warm again." }, { "icecap_8", "Cold keeps things. Old snow, old stories, small flowers." } },
    ["Black Lotus"] = { { "black_lotus", "Black Lotus. The rarest flower in Azeroth. Hold it for a moment before you put it away. You may not see another for a long time." }, { "black_lotus_2", "Another Black Lotus. Luck like this deserves a quiet moment of thanks." }, { "black_lotus_3", "Darker than the night sky, and just as full of stars, if you look closely." }, { "black_lotus_4", "Black Lotus. Hold it under the moon. The petals take the light and keep it." }, { "black_lotus_5", "Rare things are a gift, not a debt. Enjoy this one." }, { "black_lotus_6", "Some herbalists search for years and never find one. Today, you did." }, { "black_lotus_7", "It grows only in the hardest places. Beauty that asks a lot of the ground beneath it." }, { "black_lotus_8", "Quiet, now. Something rare is in your hands." } },
    ["Wilted Peacebloom"] = { { "wilted_peacebloom", "Wilted Peacebloom. It's had a hard season, but it's still a flower. Gently does it." }, { "wilted_peacebloom_2", "Drooping, but rooted. With some rain, it'll stand again." }, { "wilted_peacebloom_3", "A tired little bloom. Everyone has days like that." } },
    ["Stunted Silverleaf"] = { { "stunted_silverleaf", "Stunted Silverleaf. Small for its age, and none the worse for it." }, { "stunted_silverleaf_2", "Short stems in thin soil. It did what it could with what it had." }, { "stunted_silverleaf_3", "Not every plant grows tall. They all reach for the light anyway." } },
    ["Marefoil"] = { { "marefoil", "Marefoil. A new leaf for the herbalist's book. Turn it over and learn its shape." }, { "marefoil_2", "Unfamiliar herbs are a gift. The world still has things to show you." }, { "marefoil_3", "Smell it, if you like, and remember it. That's how every herb you know became known." }, { "marefoil_4", "The first time you hold a herb, it's a stranger. By the tenth, it's a friend." }, { "marefoil_5", "Marefoil. Even after all this time, the forest keeps surprising us." } },
    ["Demonsage"] = { { "demonsage", "Demonsage. A sage that grew where something dark once passed. It made medicine of it anyway." }, { "demonsage_2", "The name's grim. The plant is just a plant, doing its best in hard soil." }, { "demonsage_3", "Sage has always been a cleanser. Perhaps this one is cleaning up after someone else." }, { "demonsage_4", "Darkness passes through places. Green things outlast it." }, { "demonsage_5", "Careful hands, steady breath. It's only a herb." } },
    ["Death Lotus"] = { { "death_lotus", "Death Lotus. It grows on Hyjal, the sacred mountain, where the World Tree Nordrassil stands." }, { "death_lotus_2", "On Hyjal, the ancestors gave everything to save the world. The flowers grow from that ground." }, { "death_lotus_3", "A grave name for a flower. On Hyjal, endings and beginnings grow side by side." }, { "death_lotus_4", "Hold it a moment. Every flower on this mountain is part of a very old story." }, { "death_lotus_5", "Wisps are said to drift on Hyjal at night. Perhaps one is watching over this flower." }, { "death_lotus_6", "Rare and dark and still a lotus. It opens toward the light like any other." } },
    ["Frilled Lichen"] = { { "frilled_lichen", "Frilled Lichen. A lichen is two lives in one: a fungus and a tiny green partner, living as a single thing." }, { "frilled_lichen_2", "Lichens grow so slowly that a patch the size of your hand may be older than you." }, { "frilled_lichen_3", "Lichen grows on bare rock and slowly turns it into soil. Every forest started with something like this." }, { "frilled_lichen_4", "A lucky find, tucked among the herbs. Partnerships often go unnoticed." }, { "frilled_lichen_5", "Its frills are delicate. Wrap it carefully." } },
    ["Rosecap"] = { { "rosecap", "Rosecap. A blush of rose among the green. A small, rare kindness from the ground." }, { "rosecap_2", "Rare things hide among common ones. Keep looking closely." }, { "rosecap_3", "A little colour you didn't expect. The best gifts are like that." }, { "rosecap_4", "Rosecap. Hold it to the light and see the colour deepen." }, { "rosecap_5", "Found, not taken. That's the herbalist's luck." } },
    ["Stranglevine"] = { { "stranglevine", "Stranglevine. Vines climb toward the light using others for support. Not cruelty, just reaching." }, { "stranglevine_2", "It winds and grips and climbs. Persistence, mostly." }, { "stranglevine_3", "Untwine it slowly. Vines remember how they grew." }, { "stranglevine_4", "A rare tangle. The forest keeps a few surprises close to the ground." }, { "stranglevine_5", "Every vine is a path the plant took toward the sun." } },
    ["Commonplace Herb Seeds"] = { { "commonplace_herb_seeds", "Seeds. A whole plant, folded small and waiting. Keep them somewhere dry." }, { "commonplace_herb_seeds_2", "Some seeds wait years for the right moment. There's no rushing them, and no need." }, { "commonplace_herb_seeds_3", "Plant one, and you'll have given something back to the world." } },
    ["Uncommon Herb Seeds"] = { { "uncommon_herb_seeds", "Uncommon seeds. A little more promise in each one." }, { "uncommon_herb_seeds_2", "Seeds don't all sprout at once. Some wait, in case the first year is a hard one. Wise." }, { "uncommon_herb_seeds_3", "Tend them well. Growing something is a quiet kind of hope." } },
    ["Unusual Herb Seeds"] = { { "unusual_herb_seeds", "Unusual seeds. Who knows what they'll become? That's half the joy." }, { "unusual_herb_seeds_2", "A seed is a promise that hasn't been kept yet." }, { "unusual_herb_seeds_3", "Hold them in your palm a moment. All that life, so small." } },
    ["Scarce Herb Seeds"] = { { "scarce_herb_seeds", "Scarce seeds. Rare, and full of possibility. Plant them somewhere they'll be cared for." }, { "scarce_herb_seeds_2", "The rarest things often start the smallest." }, { "scarce_herb_seeds_3", "These ones are precious. A garden is only ever a series of small faiths." } },
    ["Timberling Sprout"] = { { "timberling_sprout", "A timberling sprout. Little tree-spirits grow by the lake here. This one's young. Be gentle with it." }, { "timberling_sprout_2", "Timberlings are part of the forest's own life. Even the sprouts are a little bit awake." }, { "timberling_sprout_3", "Small, green, and alive. Teldrassil's children come in many shapes." } },
}
ns.HERB_CALM = {
    { "calm1", "Breathe. The forest isn't going anywhere, and neither is the next herb." },
    { "calm2", "Listen for a moment. Wind, birds, water. You're allowed to just be here." },
    { "calm3", "You don't have to hurry. Gathering is a kind of listening." },
    { "calm4", "Look up from the map, if you like. Somewhere nearby, something beautiful is happening that nobody else will see." },
    { "calm5", "Every herb you pick will grow back. That's the oldest lesson in the druid's path." },
    { "calm6", "The world is big, and you are in it. That's enough for today." },
    { "calm7", "Kneel. Pick slowly. Say thank you, if you like. The druids always did." },
    { "calm8", "The roots go deeper than you can see. Somewhere under your feet, the whole forest is holding hands." },
    { "calm9", "Your hands know this path now. Let them. The rest of you can simply look around." },
    { "calm10", "Picking, walking, picking. A rhythm like this can hold a busy mind, if you let it." },
    { "calm11", "Look at the shape of the next leaf you see. No two are the same." },
    { "calm12", "A herbalist's hands smell green at the end of the day. That's a good smell to fall asleep to." },
    { "calm13", "The forest isn't a collection of trees. It's one long partnership between roots, fungi, and light." },
    { "calm14", "You're one of the forest's gatherers now. Take only what you need, and say thank you." },
    { "calm15", "Every plant you pass is doing something quiet and remarkable, simply by being alive." },
    { "calm16", "When the gathering's done, rest your hands. They've worked well today." },
    { "calm17", "Slow down a little. The best herbs are found by those who look carefully." },
    { "calm18", "The herbalist's walk is a slow one. That's half the pleasure." },
    { "calm19", "Each plant has its own place in the world. You're visiting each one." },
    { "calm20", "Look at the ground as you walk. There's a whole world down there." },
    { "calm21", "Every herb has a story: where it grows, what it needs, what it gives." },
    { "calm22", "Leave a few behind because the next traveller might need them, and so might the bees." },
    { "calm23", "Look up between herbs, sometimes. The sky's worth a glance too." },
    { "calm24", "Bees work a meadow flower by flower, never the whole field at once. One herb, then the next." },
    { "calm25", "Moss keeps the ground cool and damp for every root above it. Small, slow work holds a forest up." },
    { "calm26", "Somewhere under this soil a seed is waiting for its year. Waiting is part of growing too." },
    { "calm27", "Pollen drifts from flower to flower on the wind and on small wings. The whole meadow is quietly in touch." },
    { "calm28", "Kneel by the plant and the forest shrinks to an arm's reach. Sometimes that's the right size for a day." },
    { "calm29", "The trees here have stood through storms none of us saw. Their roots are holding while you work." },
    { "calm30", "A root grows towards water it can't see. Roots trust the dark like that." },
    { "calm31", "The forest floor is made of last year's leaves. Nothing that falls here is wasted." },
    { "calm32", "Even on a grey day the leaves are still drinking light. Grey light is still light." },
    { "calm33", "Petals open in the morning and close at dusk, and neither one is a failure." },
    { "calm34", "Every herb in your satchel spent a whole season becoming itself. Handle them like that." },
    { "calm35", "The undergrowth hums with small lives going about their work. You're working alongside them." },
    { "calm36", "A spider has hung its thread between two stems. Mind it as you reach." },
    { "calm37", "Herbs don't grow in straight lines, and neither does a good path through them." },
    { "calm38", "Each leaf is a tiny workshop, turning light and air into living things. Thousands of them, all around you." },
    { "calm39", "A single seed carries a whole tree folded up inside it. Small things can hold a great deal." },
    { "calm40", "Some plants fold their leaves when they're touched. Gentleness is felt, even here." },
    { "calm41", "The same spiral turns in a pine cone, a flower's heart and a snail's shell. The world repeats its good ideas." },
    { "calm42", "Thorns and soft leaves often grow side by side. Both belong." },
    { "calm43", "Dew gathers on the leaves overnight and is gone by noon. Quiet things do their work and move on." },
}
ns.SKIN = {
    { "skin1", "Thank you, little one. Nothing of you will be wasted." },
    { "skin2", "Every hunt is a debt. Carry it lightly, and use it well." },
    { "skin3", "Gently now. The beast has given what it had. Its spirit runs on, somewhere green and quiet." },
    { "skin4", "In a few days this will be a cloak, or a quiver. And still, somehow, a little bit wild." },
    { "skin5", "The kaldorei never took more than the forest could spare. Neither do you." },
    { "skin6", "Rest now, friend. The forest will take back what's left." },
    { "skin7", "Gently now. Every hide was once a living thing." },
    { "skin8", "Take only what you need, and thank what gave it." },
    { "skin9", "Rest now, little one. Your part in the forest is done." },
    { "skin10", "The kaldorei hunt with respect. Every creature is part of the balance." },
    { "skin11", "Nothing wasted. That's the old way." },
    { "skin12", "A quiet thanks, before you move on." },
    { "skin13", "Every life feeds another. That's the forest's way." },
    { "skin14", "The hide kept this creature warm through every winter it knew. It will keep someone warm again." },
    { "skin15", "Quick, careful hands are the kindest kind. The beast feels none of this now." },
    { "skin16", "Hold still a moment before you rise. A life ended here, and it deserves that moment." },
    { "skin17", "A beast lives by the wind, by scent, by the ground underfoot. Breathe the same wind it knew." },
    { "skin18", "The animal's warmth is leaving the hide. Let your hands slow down while it does." },
    { "skin19", "Wild things don't hold grudges. They live, and they run, and then they rest." },
    { "skin20", "The hide carries a whole life in it: old scars, thick winter fur, the wear of long running." },
    { "skin21", "Every pelt in a quiver or a cloak once moved through the trees as you do now. Remember that when you wear it." },
}
